#!/usr/bin/env python3
"""Bounded emulator crash sweep. Incomplete journals never count as success."""
import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import time
import xml.etree.ElementTree as ET
from pathlib import Path
import matrix

# Keep generated bytecode out of the source tree.
import sys
sys.dont_write_bytecode = True

ROOT = matrix.ROOT
FATAL = re.compile(r'Guru Meditation|Software Failure|\bGURU\b|Illegal instruction:|Address Error|Bus Error', re.I)


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def verdict(rows, text, run_rc, fatal=False):
    """Strict, per-id transcript accounting (also exercised by host negatives)."""
    events = {}
    done = False
    bad_journal = False
    order = []
    for line in text.splitlines():
        parts = line.split('\t')
        if len(parts) != 5:
            bad_journal = True
            continue
        ident, event, rc, stack, broke = parts
        order.append((ident, event))
        try:
            vals = int(rc), int(stack), int(broke)
        except ValueError:
            bad_journal = True
            continue
        if ident == 'SUITE' and event == 'DONE':
            if done or vals != (0, 0, 0):
                bad_journal = True
            done = True
        else:
            events.setdefault(ident, []).append((event,) + vals)
    expected_order = [(r['id'], event) for r in rows for event in ('START', 'END')] + [('SUITE', 'DONE')]
    normalized = [(ident, 'END' if event in ('LATE', 'TIMEOUT', 'UNREPLIED_CLOSE') else event)
                  for ident, event in order]
    if normalized != expected_order[:len(normalized)] or (done and len(normalized) != len(expected_order)):
        bad_journal = True
    expected = {r['id'] for r in rows}
    if set(events) - expected:
        bad_journal = True
    # Attribute a dead guest to its last started child. A complete valid
    # prefix remains covered; only the unstarted suffix is retried. Missing
    # DONE without a failed/incomplete child still fails (e.g. truncation).
    active = next((r['id'] for r in reversed(rows) if events.get(r['id'])), None)
    active_seq = events.get(active, [])
    interrupted_guest = (not done and run_rc != 0 and active_seq
                         and active_seq[-1][0] != 'END' and not bad_journal)
    results = []
    for row in rows:
        seq = events.get(row['id'], [])
        reason = None
        if fatal and (not interrupted_guest or row['id'] == active):
            reason = 'fatal emulator/guest exception in batch'
        elif bad_journal:
            reason = 'malformed, duplicate or foreign journal'
        elif len(seq) != 2 or seq[0] != ('START', 0, row['stack'], 0) or seq[-1][0] != 'END':
            reason = 'missing completion, timeout or infrastructure failure: ' + repr(seq)
        elif seq[-1][1] not in row['allowed']:
            reason = 'unexpected return code %d' % seq[-1][1]
        elif seq[-1][2] != row['stack']:
            reason = 'actual child stack %d, requested %d' % (seq[-1][2], row['stack'])
        elif row['mode'] == 'exit' and seq[-1][3] != 0:
            reason = 'plain exit case required interruption'
        elif (not done or run_rc != 0) and not interrupted_guest:
            reason = 'incomplete or failed emulator run (%d)' % run_rc
        results.append(dict(row, passed=reason is None, reason=reason,
                            events=seq, run_rc=run_rc))
    return results


def binaries(ns, policy):
    found = {}
    for tool, spec in policy.items():
        if ns.package:
            choices = [ns.package / 'C' / tool, ns.package / tool,
                       ns.package / 'Wireless' / tool, ns.package / 'Developer/Profile' / tool]
        elif spec['binary'].startswith('@'):
            choices = ([ROOT / 'install/Installer'] if tool == 'Installer' else
                       [ROOT / 'third_party/wirelessmanager/WirelessManager'] if tool == 'WirelessManager' else
                       [ns.clients / {'ssh': 'dbclient'}.get(tool, tool)])
        else:
            choices = [ns.build / spec['binary']]
        path = next((p for p in choices if p.is_file()), None)
        if path is None:
            raise ValueError('missing shipped executable %s: %s (never skipped)' % (tool, choices))
        if path.read_bytes()[:4] != b'\x00\x00\x03\xf3':
            raise ValueError('not an Amiga hunk executable: ' + str(path))
        found[tool] = path
    if ns.package:
        # A newly packaged executable cannot disappear behind source inventory.
        actual = {p.name for folder in ('C', 'Wireless', 'Developer/Profile', '.')
                  if (ns.package / folder).is_dir() for p in (ns.package / folder).iterdir()
                  if p.is_file() and p.read_bytes()[:4] == b'\x00\x00\x03\xf3'}
        if actual - set(found):
            raise ValueError('uncovered packaged tools: ' + repr(actual - set(found)))
    return found


def batch(ns, rows, paths, state, ordinal):
    stage = ns.output / 'stage'
    if stage.exists():
        shutil.rmtree(stage)
    (stage / 'c').mkdir(parents=True)
    (stage / 'libs').mkdir()
    shutil.copytree(ROOT / 'tests/netstack/devs', stage / 'devs')
    # Private guest files only. No installed host or real-machine settings.
    shutil.copy2(ns.output / 'bin/CliControl', stage / 'c/CliControl')
    for tool in {r['tool'] for r in rows}:
        shutil.copy2(paths[tool], stage / 'c' / tool)
    if state == 'present':
        shutil.copy2(ns.library, stage / 'libs/bsdsocket.library')
        if ns.tls and ns.tls.is_file():
            shutil.copy2(ns.tls, stage / 'libs/tls.library')
    # An unavailable device is deliberate: independent of NIC/peer/ROM assets.
    # Runtime parser/error/loopback paths and resident shutdown are exercised;
    # successful wire protocols remain the existing integration harnesses' job.
    (stage / 'devs/NetInterfaces/eth0').write_text('DEVICE=missing.device\nUNIT=0\nCONFIGURE=STATIC\nADDRESS=10.77.0.2\nNETMASK=255.255.255.0\n')
    (stage / 'cli-input').write_text('CLI fixture\n')
    # Guest argument files do not go through a Shell or an injection-prone eval.
    casefile = stage / 'cli-cases.tsv'
    casefile.write_text(''.join('%s\t%d\t%s\t%d\tSYS:c/%s\t%s\n' %
                               (r['id'], r['stack'], 'I' if r['mode'] == 'interrupt' else 'E',
                                r.get('seconds', 1 if r['mode'] == 'interrupt' else 3), r['tool'], r['arguments']) for r in rows))
    tag = 'clicrash-%s-%s-%04d' % (ns.token, state, ordinal)
    hd = ROOT / 'build' / ('amiberry-testhd-' + tag)
    env = dict(os.environ, AMINETXDUO_RUN_TAG=tag,
               AMINETXDUO_GUEST_STACK='65536', AMINETXDUO_AMIBERRY_BACKEND='none')
    # No active network is requested. This suite tests commands independently
    # of the bench; none means boardless rather than another NAT network test.
    cmd = [str(ROOT / 'tools/amiberry-run.sh'), '-m', ns.model, '-B', 'none',
           '-t', str(max(90, sum(r.get('seconds', 3) + 4 for r in rows) + 30)), str(ns.output / 'bin/CliCrash'),
           str(casefile), str(stage / 'c'), str(stage / 'libs'), str(stage / 'devs'),
           str(stage / 'cli-input')]
    logfile = ns.output / ('%s-%04d.log' % (state, ordinal))
    journal_path = hd / 'cli-results.tsv'
    started = time.monotonic()
    last_change = started
    last_text = ''
    current_seconds = 3
    watchdog = False
    with logfile.open('w') as log:
        proc = subprocess.Popen(cmd, env=env, cwd=ROOT, stdout=log,
                                stderr=subprocess.STDOUT, start_new_session=True)
        try:
            while proc.poll() is None:
                text = journal_path.read_text(errors='replace') if journal_path.exists() else ''
                if text != last_text:
                    last_text, last_change = text, time.monotonic()
                    last_id = text.splitlines()[-1].split('\t')[0] if text else ''
                    current_seconds = next((r.get('seconds', 3) for r in rows if r['id'] == last_id), 3)
                # Bootstrap has its own deadline. Child grace is per case;
                # add shutdown time and bounded host lag.
                if time.monotonic() - last_change > (current_seconds + 25 if last_text else 60):
                    watchdog = True
                    proc.terminate()  # amiberry-run's trap reaps its guest.
                    try:
                        proc.wait(timeout=12)
                    except subprocess.TimeoutExpired:
                        os.killpg(proc.pid, 9)
                        proc.wait()
                    break
                time.sleep(0.1)
        finally:
            if proc.poll() is None:
                proc.terminate()
                proc.wait(timeout=12)
    text = journal_path.read_text(errors='replace') if journal_path.exists() else ''
    saved = ns.output / ('%s-%04d.tsv' % (state, ordinal))
    saved.write_text(text)
    logtext = logfile.read_text(errors='replace')
    results = verdict(rows, text, proc.returncode if not watchdog else 124,
                      bool(FATAL.search(logtext)))
    for r in results:
        r.update(state=state, batch=ordinal, log=logfile.name, journal=saved.name)
    # Retain bounded final output alongside the failure transcript.
    last_output = hd / 'cli-output.txt'
    if last_output.is_file():
        (ns.output / ('%s-%04d-output.txt' % (state, ordinal))).write_bytes(last_output.read_bytes()[-65536:])
    # Journals/logs retain the evidence; disposable guest disks contain copied
    # executables and must not accumulate across thousands of cases.
    shutil.rmtree(hd, ignore_errors=True)
    for pattern in ('amiberry-' + tag + '.*', 'amiberry-serial-' + tag + '.*'):
        for artifact in (ROOT / 'build').glob(pattern):
            if artifact.is_file():
                artifact.unlink()
    return results


def controls(ns):
    """Real guest negatives must reach the child, not just fail to boot."""
    paths = {'CliControl': ns.output / 'bin/CliControl', 'Installer': ns.output / 'bin/CliControl'}
    (ns.output / 'control-inputs.json').write_text(json.dumps({
        'model': ns.model, 'selected': ns.control_kind,
        'supervisor_sha256': digest(ns.output / 'bin/CliCrash'),
        'control_sha256': digest(ns.output / 'bin/CliControl')}, indent=2) + '\n')
    results = []
    for index, (kind, args, mode) in enumerate((
            ('normal', '', 'exit'), ('break', 'BREAK', 'interrupt'), ('window', 'WINDOW', 'interrupt'), ('delayed-window', 'WINDOW WAITGUI', 'interrupt'), ('gadget', 'GADGET', 'interrupt'), ('key', 'KEY', 'interrupt'), ('raw', 'RAW', 'interrupt'), ('installer', 'GADGET', 'interrupt'),
            ('badrc', 'BADRC', 'exit'), ('late', 'BREAK', 'exit'),
            ('hang', 'HANG', 'exit'), ('crash', 'CRASH', 'exit'))):
        if ns.control_kind and kind not in ns.control_kind:
            continue
        for stack in (4096, 8192):
            row = dict(id='control', tool='Installer' if kind == 'installer' else 'CliControl', kind=kind, arguments=args,
                       mode=mode, allowed=[0], stack=stack, binary='CliControl')
            result = batch(ns, [row], paths, 'control', index * 2 + (stack == 8192))[0]
            ev = result['events']
            started = bool(ev and ev[0] == ('START', 0, stack, 0))
            if kind in ('normal', 'break', 'window', 'delayed-window', 'gadget', 'key', 'raw', 'installer'):
                good = result['passed']
            elif kind == 'badrc':
                good = started and len(ev) == 2 and ev[1] == ('END', 42, stack, 0) and not result['passed']
            elif kind == 'late':
                good = started and len(ev) == 2 and ev[1] == ('LATE', 0, stack, 1) and not result['passed']
            elif kind == 'hang':
                good = started and len(ev) == 2 and ev[1][0] == 'TIMEOUT' and not result['passed']
            else:
                good = started and not any(e[0] == 'END' for e in ev) and result['reason'] == 'fatal emulator/guest exception in batch'
            result['control_detected'] = good
            results.append(result)
            (ns.output / 'controls.json').write_text(json.dumps(results, indent=2) + '\n')
            print('cli_control=%s kind=%s stack=%d' % ('PASS' if good else 'FAIL', kind, stack), flush=True)
            if not good:
                return False
    return True


def write_results(ns, results):
    (ns.output / 'results.json').write_text(json.dumps(results, indent=2) + '\n')
    suite = ET.Element('testsuite', name='shipped-cli-crashes', tests=str(len(results)),
                       failures=str(sum(not r['passed'] for r in results)))
    for r in results:
        case = ET.SubElement(suite, 'testcase', classname=r['tool'],
                             name='%s/%s/%s/stack%d' % (r.get('state', ''), r['id'], r['kind'], r['stack']))
        if not r['passed']:
            ET.SubElement(case, 'failure', message=r['reason']).text = json.dumps(r)
    ET.ElementTree(suite).write(ns.output / 'junit.xml', encoding='utf-8', xml_declaration=True)


def sweep(ns, rows, paths):
    results = []
    for state in ns.state or ['present', 'missing']:
        pending = list(rows)
        ordinal = 0
        while pending:
            group = pending[:ns.batch_size]
            current = batch(ns, group, paths, state, ordinal)
            ordinal += 1
            started = [r for r in current if r['events']]
            if started:
                # A failed child can kill this guest. Only unstarted suffixes
                # are retried in a fresh guest; completed cases are not rerun.
                results.extend(started)
                completed = {r['id'] for r in started}
                pending = [r for r in pending if r['id'] not in completed]
            else:
                # No child started: this is a rig/bootstrap failure, not a
                # reason to boot thousands of identical broken guests.
                results.extend(current)
                for row in pending[len(group):]:
                    results.append(dict(row, passed=False, reason='not run after bootstrap failure',
                                        events=[], run_rc=1, state=state, batch=ordinal))
                pending = []
            write_results(ns, results)
            bad = sum(not r['passed'] for r in current)
            print('cli_batch state=%s batch=%d attempted=%d failures=%d pending=%d' %
                  (state, ordinal - 1, len(started), bad, len(pending)), flush=True)
    return results


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('-b', '--build', type=Path, required=True)
    ap.add_argument('--clients', type=Path, required=True)
    ap.add_argument('--package', type=Path)
    ap.add_argument('--library', type=Path)
    ap.add_argument('--tls', type=Path)
    ap.add_argument('--model', default='A1200', choices=['A1200', 'A600'])
    ap.add_argument('--output', type=Path, required=True)
    ap.add_argument('--batch-size', type=int, default=128)
    ap.add_argument('--tool', action='append')
    ap.add_argument('--state', action='append', choices=['present', 'missing'])
    ap.add_argument('--control-kind', action='append', choices=['normal', 'break', 'window', 'delayed-window', 'gadget', 'key', 'raw', 'installer', 'badrc', 'late', 'hang', 'crash'], help='focused negative-control debugging, controls-only required')
    ap.add_argument('--helper-bin', type=Path, help='prebuilt helpers from this source for a separate emulator host')
    ap.add_argument('--controls-only', action='store_true', help='validate supervisor without shipping binaries')
    ns = ap.parse_args()
    if ns.control_kind and not ns.controls_only:
        ap.error('--control-kind requires --controls-only; full sweeps always run all controls')
    for key in ('build', 'clients', 'output'):
        setattr(ns, key, getattr(ns, key).resolve())
    ns.library = ns.library or ns.build / 'src/bsdsocket/bsdsocket.library'
    ns.tls = ns.tls or ns.build / 'src/tlslib/tls.library'
    if not ns.controls_only and not ns.library.is_file():
        raise ValueError('missing library for present-state cases')
    if not 1 <= ns.batch_size <= 256:
        raise ValueError('batch size must be 1..256')
    ns.output.mkdir(parents=True, exist_ok=True)
    ns.token = '%x-%x' % (os.getpid(), time.time_ns())
    if ns.helper_bin:
        (ns.output / 'bin').mkdir(exist_ok=True)
        for name in ('CliCrash', 'CliControl'):
            src = ns.helper_bin / name
            if src.read_bytes()[:4] != b'\x00\x00\x03\xf3':
                raise ValueError('invalid prebuilt helper: ' + str(src))
            shutil.copy2(src, ns.output / 'bin' / name)
    else:
        subprocess.run(['bash', str(Path(__file__).with_name('build.sh')), str(ns.output / 'bin')], check=True)
    if not controls(ns):
        return 1
    if ns.controls_only:
        return 0
    policy = matrix.validate()
    paths = binaries(ns, policy)
    rows = matrix.matrix(policy=policy)
    if ns.tool:
        unknown = set(ns.tool) - set(policy)
        if unknown:
            raise ValueError('unknown tools: ' + str(unknown))
        rows = [r for r in rows if r['tool'] in ns.tool]
    provenance = {t: {'path': str(p), 'sha256': digest(p)} for t, p in paths.items()}
    (ns.output / 'inputs.json').write_text(json.dumps({'binaries': provenance,
        'library': {'path': str(ns.library), 'sha256': digest(ns.library)},
        'policy_sha256': digest(matrix.POLICY), 'generator_sha256': digest(Path(matrix.__file__)), 'model': ns.model,
        'tls_sha256': digest(ns.tls) if ns.tls.is_file() else None, 'helper_sha256': digest(ns.output / 'bin/CliCrash'), 'states': ns.state or ['present', 'missing'],
        'case_sha256': hashlib.sha256(json.dumps(rows, sort_keys=True).encode()).hexdigest(),
        'partial': bool(ns.tool or ns.state), 'cases': len(rows)}, indent=2) + '\n')
    results = sweep(ns, rows, paths)
    shutil.rmtree(ns.output / 'stage', ignore_errors=True)
    bad = sum(not r['passed'] for r in results)
    print('cli_crashes=%s cases=%d failures=%d partial=%s' %
          ('FAIL' if bad else 'PASS', len(results), bad, bool(ns.tool or ns.state)))
    return 1 if bad else 0

if __name__ == '__main__':
    raise SystemExit(main())
